public int retryFailedMessages(MailQueue queue, int maxAttempts) {
        int count = 0;
        for (Message message : queue.findFailed()) {
            if (message.getAttempts() < maxAttempts) {
                queue.requeue(message);
                count++;
            }
        }
        return count;
    }

def compute_file_digest(path):
    """Calculate a SHA-256 checksum without loading the whole file into memory."""
    digest = hashlib.sha256()
    with open(path, "rb") as stream:
        for chunk in iter(lambda: stream.read(65536), b""):
            digest.update(chunk)
    return digest.hexdigest()

public boolean reserveStock(InventoryRepository repo, String sku, int quantity) {
